const esc=x=>String(x).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]));
const defaults={n:8,method:'mid',angle:0,power:5,b:1,inner:0,sector:4};
export function normaliseModels(raw={}){const s={...defaults};for(const [k,min,max,step] of [['n',2,40,1],['angle',0,360,5],['power',1,40,1],['b',.1,1,.1],['inner',0,1,.25],['sector',1,8,1]]){const x=raw?.[k];if(typeof x==='number'&&Number.isFinite(x))s[k]=Math.round(Math.max(min,Math.min(max,x))/step)*step;}if(['left','mid','right'].includes(raw?.method))s.method=raw.method;return s;}
export function riemann(n,method){const shift={left:0,mid:.5,right:1}[method];return Array.from({length:n},(_,i)=>((i+shift)/n)**2/n).reduce((a,b)=>a+b,0);}
export const directional=angle=>2*Math.cos(angle*Math.PI/180)+4*Math.sin(angle*Math.PI/180);
export const sectorArea=(inner,k)=>Math.PI*k/4*(4-inner*inner)/2;
const fmt=x=>Math.abs(x)<1e-10?'0':Number(x.toFixed(6)).toLocaleString('ru-RU',{maximumFractionDigits:6});
const svg=(label,body)=>'<svg viewBox="0 0 400 260" role="img" aria-label="'+label+'">'+body+'</svg>';
const path=(points,color='#174c43',width=3)=>'<path d="M'+points.map(p=>p.join(',')).join(' L')+'" fill="none" stroke="'+color+'" stroke-width="'+width+'"/>';
const axes='<path d="M40 20V220H370" fill="none" stroke="#758c7c"/><text x="365" y="245">x</text><text x="15" y="30">y</text><text x="28" y="240">0</text>';
const slider=(name,label,min,max,step,value)=>'<label class="model-control">'+label+' <output data-model-value="'+name+'">'+fmt(value)+'</output><input aria-label="'+label+'" data-model-field="'+name+'" type="range" min="'+min+'" max="'+max+'" step="'+esc(step)+'" value="'+value+'"></label>';
export function advancedModelOutput(id,s){
 if(id==='three'){const shift={left:0,mid:.5,right:1}[s.method],rect=Array.from({length:s.n},(_,i)=>{const h=((i+shift)/s.n)**2;return '<rect x="'+(40+320*i/s.n)+'" y="'+(220-190*h)+'" width="'+320/s.n+'" height="'+190*h+'" fill="#e2b87888" stroke="#b28b56" stroke-width=".5"/>';}).join(''),sum=riemann(s.n,s.method);return svg('Интегральная сумма для x² на [0,1]',axes+rect+path(Array.from({length:101},(_,i)=>[40+3.2*i,220-190*(i/100)**2])))+'<div class="lab-conclusion"><strong>Sₙ = '+fmt(sum)+'; I = 1/3</strong><p>|Sₙ−I| = '+fmt(Math.abs(sum-1/3))+'. Прямоугольники используют '+({left:'левые',mid:'средние',right:'правые'}[s.method])+' отмеченные точки. Для возрастающей x² левые суммы не превосходят интеграл, правые — не меньше него.</p></div>';}
 if(id==='four'){const a=s.angle*Math.PI/180,contours=[40,70,100].map(r=>'<ellipse cx="200" cy="130" rx="'+r+'" ry="'+r/Math.sqrt(2)+'" fill="none" stroke="#c1cfc0"/>').join(''),body=contours+path([[200,130],[240,50]],'#b28b56')+path([[200,130],[200+90*Math.cos(a),130-90*Math.sin(a)]])+ '<circle cx="200" cy="130" r="4" fill="#174c43"/><text x="246" y="48">∇f=(2,4)</text><text x="16" y="245">Векторы приложены в a=(1,1)</text>';return svg('Градиент и единичное направление; линии уровня f=x²+2y² схематичны',body)+'<div class="lab-conclusion"><strong>Dᵥf(1,1) = '+fmt(directional(s.angle))+'</strong><p>v=(cos θ,sin θ); Dᵥf=2cos θ+4sin θ. Максимум 2√5 ≈ '+fmt(Math.sqrt(20))+' при θ≈63,435°. Линии уровня на рисунке показаны схематично; направления векторов вычислены по выбранному углу.</p></div>';}
 if(id==='five'){const points=Array.from({length:101},(_,i)=>[40+320*i/100,220-190*(s.b*i/100)**s.power]),isOne=s.b>.999999;return svg('График x в степени n на отрезке от 0 до b',axes+path(points)+'<text x="320" y="245">b='+fmt(s.b)+'</text>'+(isOne?'<circle cx="360" cy="220" r="5" fill="white" stroke="#b28b56"/><circle cx="360" cy="30" r="5" fill="#b28b56"/>':''))+'<div class="lab-conclusion"><strong>'+(isOne?'Поточечно, но не равномерно; sup ошибки = 1':'Равномерно к нулю; sup ошибки = '+fmt(s.b**s.power))+'</strong><p>'+(isOne?'Предел равен 0 на [0,1), а в точке 1 равен 1. Ошибка в самой точке 1 равна 0. Точная верхняя граница 1 достигается только в пределе x→1− и не является максимумом ошибки.':'Здесь b<1 и предел всюду равен 0. Оценка bⁿ→0 действует одновременно для всех x∈[0,b].')+'</p></div>';}
 const alpha=s.sector*Math.PI/4,outer=Array.from({length:81},(_,i)=>[200+100*Math.cos(alpha*i/80),135-100*Math.sin(alpha*i/80)]),inner=Array.from({length:81},(_,i)=>[200+50*s.inner*Math.cos(alpha*(80-i)/80),135-50*s.inner*Math.sin(alpha*(80-i)/80)]);return svg('Кольцевой сектор с внешним радиусом 2','<path d="M'+[...outer,...inner].map(p=>p.join(',')).join(' L')+' Z" fill="#e2b87888" stroke="#174c43"/><circle cx="200" cy="135" r="3" fill="#174c43"/><text x="12" y="250">a='+fmt(s.inner)+', α='+s.sector+'π/4, R=2</text>')+'<div class="lab-conclusion"><strong>Площадь = '+fmt(s.sector*(4-s.inner**2)/8)+'π ≈ '+fmt(sectorArea(s.inner,s.sector))+'</strong><p>∫₀ᵅ∫ₐ² r drdθ = α(4−a²)/2. Множитель r — якобиан полярной замены. Выражение α(2−a), полученное без r, не вычисляет площадь этой области.</p></div>';
}
export function advancedLab(c,s){let controls='';if(c.id==='three')controls=slider('n','Число частей n',2,40,1,s.n)+'<label>Отмеченные точки<select data-model-field="method">'+[['left','Левые'],['mid','Средние'],['right','Правые']].map(([v,t])=>'<option value="'+v+'" '+(s.method===v?'selected':'')+'>'+t+'</option>').join('')+'</select></label>';if(c.id==='four')controls=slider('angle','Угол θ в градусах',0,360,5,s.angle);if(c.id==='five')controls=slider('power','Номер n',1,40,1,s.power)+slider('b','Правая граница b',.1,1,.1,s.b);if(c.id==='six')controls=slider('inner','Внутренний радиус a',0,1,.25,s.inner)+slider('sector','Множитель k в α=kπ/4',1,8,1,s.sector);return '<p class="eyebrow">Вычисляемый пример / '+c.number+'</p><h2>'+({three:'Интегральные суммы для x²',four:'Производная по направлению',five:'Зависимость сходимости от области',six:'Якобиан в полярных координатах'}[c.id])+'</h2><section class="lab-panel advanced-model"><div class="lab-controls">'+controls+'</div><div id="advanced-model-output" aria-live="polite">'+advancedModelOutput(c.id,s)+'</div></section><h2 class="section-space">Разобранные задачи</h2>'+c.workedExamples.map(e=>'<details class="deep worked-example" open><summary>'+e.title+'</summary><p>'+esc(e.statement)+'</p><ol>'+e.steps.map(step=>'<li>'+step+'</li>').join('')+'</ol><div class="formula">'+esc(e.result)+'</div></details>').join('');}
